@asynccontextmanager
async def lifespan(server: MCPServer) -> AsyncIterator[AppCtx]:
    pool = await Pool.connect()
    try:
        yield AppCtx(pool=pool)
    finally:
        await pool.close()

mcp = MCPServer("Books", lifespan=lifespan)

@mcp.tool()
async def count(genre: str, ctx: Context[AppCtx]) -> int:
    return await ctx.request_context.lifespan_context.pool.count(genre)
```

